#include <vector>
#include <unordered_map>
#include <algorithm>
#include <cmath>

class Solution {
public:
    double maxTriangleArea(std::vector<std::vector<int>>& points) {
        std::unordered_map<int, std::vector<int>> x_pts, y_pts;
        int min_x = 1e9, max_x = -1e9;
        int min_y = 1e9, max_y = -1e9;

        for (const auto& pt : points) {
            int x = pt[0], y = pt[1];
            x_pts[x].push_back(y);
            y_pts[y].push_back(x);
            min_x = std::min(min_x, x);
            max_x = std::max(max_x, x);
            min_y = std::min(min_y, y);
            max_y = std::max(max_y, y);
        }

        double max_area = 0.0;

        for (const auto& [x, ys] : x_pts) {
            if (ys.size() >= 2) {
                int min_v = *std::min_element(ys.begin(), ys.end());
                int max_v = *std::max_element(ys.begin(), ys.end());
                int base = max_v - min_v;
                int height = std::max(std::abs(x - min_x), std::abs(x - max_x));
                double area = 0.5 * base * height;
                if (area > max_area) max_area = area;
            }
        }

        for (const auto& [y, xs] : y_pts) {
            if (xs.size() >= 2) {
                int min_v = *std::min_element(xs.begin(), xs.end());
                int max_v = *std::max_element(xs.begin(), xs.end());
                int base = max_v - min_v;
                int height = std::max(std::abs(y - min_y), std::abs(y - max_y));
                double area = 0.5 * base * height;
                if (area > max_area) max_area = area;
            }
        }

        return max_area;
    }
};

import java.util.*;

class Solution {
    public double maxTriangleArea(int[][] points) {
        Map<Integer, List<Integer>> xPts = new HashMap<>();
        Map<Integer, List<Integer>> yPts = new HashMap<>();
        int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE;
        int minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;

        for (int[] pt : points) {
            int x = pt[0], y = pt[1];
            xPts.computeIfAbsent(x, k -> new ArrayList<>()).add(y);
            yPts.computeIfAbsent(y, k -> new ArrayList<>()).add(x);
            minX = Math.min(minX, x);
            maxX = Math.max(maxX, x);
            minY = Math.min(minY, y);
            maxY = Math.max(maxY, y);
        }

        double maxArea = 0.0;

        for (var entry : xPts.entrySet()) {
            int x = entry.getKey();
            List<Integer> ys = entry.getValue();
            if (ys.size() >= 2) {
                int minV = Collections.min(ys);
                int maxV = Collections.max(ys);
                int base = maxV - minV;
                int height = Math.max(Math.abs(x - minX), Math.abs(x - maxX));
                double area = 0.5 * base * height;
                if (area > maxArea) maxArea = area;
            }
        }

        for (var entry : yPts.entrySet()) {
            int y = entry.getKey();
            List<Integer> xs = entry.getValue();
            if (xs.size() >= 2) {
                int minV = Collections.min(xs);
                int maxV = Collections.max(xs);
                int base = maxV - minV;
                int height = Math.max(Math.abs(y - minY), Math.abs(y - maxY));
                double area = 0.5 * base * height;
                if (area > maxArea) maxArea = area;
            }
        }

        return maxArea;
    }
}

/**
 * @param {number[][]} points
 * @return {number}
 */
var maxTriangleArea = function(points) {
    const xPts = new Map();
    const yPts = new Map();
    let minX = Infinity, maxX = -Infinity;
    let minY = Infinity, maxY = -Infinity;

    for (const [x, y] of points) {
        if (!xPts.has(x)) xPts.set(x, []);
        xPts.get(x).push(y);

        if (!yPts.has(y)) yPts.set(y, []);
        yPts.get(y).push(x);

        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
    }

    let maxArea = 0.0;

    for (const [x, ys] of xPts.entries()) {
        if (ys.length >= 2) {
            const base = Math.max(...ys) - Math.min(...ys);
            const height = Math.max(Math.abs(x - minX), Math.abs(x - maxX));
            const area = 0.5 * base * height;
            if (area > maxArea) maxArea = area;
        }
    }

    for (const [y, xs] of yPts.entries()) {
        if (xs.length >= 2) {
            const base = Math.max(...xs) - Math.min(...xs);
            const height = Math.max(Math.abs(y - minY), Math.abs(y - maxY));
            const area = 0.5 * base * height;
            if (area > maxArea) maxArea = area;
        }
    }

    return maxArea;
};
